#!/usr/bin/env python3
"""A module using a vendored library must set the path up itself, first.

⚠️ The vendored `thehive4py` and `cortex4py` live in
`package/bin/ta_thehive_cortex/libs/`, a directory Python knows nothing about
until something puts it on `sys.path`. Two bootstraps exist and they are NOT
equivalent:

* `ta_thehive_cortex_declare` (hand-written) adds `lib/`,
  `bin/ta_thehive_cortex/` **and** `bin/ta_thehive_cortex/libs/`;
* `import_declare_test` (generated by ucc-gen) adds `lib/` and
  `bin/TA-thehive-cortex` -- note the capitals, a directory that does not
  exist. It knows nothing of the vendored libraries.

`thehive_observables.py` and `backfill_observables.py` used the second one and
import `thehive4py` a few lines below. Measured: with only `bin/` on the path,
`thehive4py` does not resolve. They survive **by accident** -- an earlier
import of `thehive` fixes `sys.path` as a SIDE EFFECT, before the line that
needs it runs.

That is a trap, not a design: reordering imports -- which is what every linter
and every tidy-up does first -- breaks two modular inputs at load time, with a
`ModuleNotFoundError` that names the library and not the reordering.

    python tools/checks/vendored_path_bootstrap.py

Exit 0 when every module that touches a vendored package declares the right
bootstrap as its first import.
"""

from __future__ import annotations

import ast
import sys
from pathlib import Path

RACINE = Path(__file__).resolve().parents[2]
BIN = RACINE / "TA-thehive-cortex" / "package" / "bin"

BON_AMORCAGE = "ta_thehive_cortex_declare"
AMORCAGE_UCC = "import_declare_test"

#: Ce que seul `ta_thehive_cortex_declare` rend atteignable.
VENDORISES = {"thehive4py", "cortex4py"}


def paquets_importes(arbre) -> set[str]:
    paquets = set()
    for noeud in ast.walk(arbre):
        if isinstance(noeud, ast.Import):
            paquets.update(al.name.split(".")[0] for al in noeud.names)
        elif isinstance(noeud, ast.ImportFrom) and noeud.module and noeud.level == 0:
            paquets.add(noeud.module.split(".")[0])
    return paquets


def premier_import(arbre) -> str | None:
    for noeud in arbre.body:
        if isinstance(noeud, ast.Import):
            return noeud.names[0].name
        if isinstance(noeud, ast.ImportFrom):
            return noeud.module
    return None


def main() -> int:
    constats = []
    for module in sorted(BIN.rglob("*.py")):
        if "libs" in module.parts or "__pycache__" in module.parts:
            continue
        if module.name in (f"{BON_AMORCAGE}.py",):
            continue
        try:
            arbre = ast.parse(module.read_text(encoding="utf-8"))
        except SyntaxError:
            continue

        paquets = paquets_importes(arbre)
        if not (paquets & VENDORISES):
            continue

        relatif = module.relative_to(RACINE)
        if BON_AMORCAGE not in paquets:
            constats.append(
                f"{relatif} imports {', '.join(sorted(paquets & VENDORISES))} but "
                f"never imports `{BON_AMORCAGE}`"
                + (f" -- it uses `{AMORCAGE_UCC}`, which does NOT add the vendored "
                   f"libs directory" if AMORCAGE_UCC in paquets else "")
            )
            continue

        premier = premier_import(arbre)
        if premier != BON_AMORCAGE:
            constats.append(
                f"{relatif} imports `{BON_AMORCAGE}` but not FIRST (first is "
                f"`{premier}`): the path is fixed after something has already "
                f"needed it"
            )

    for c in constats:
        print(f"  {c}")
    if constats:
        print()
        print("A vendored library is only importable once its directory is on")
        print("sys.path. Relying on another module's import to do it is a trap:")
        print("reordering imports breaks the module, and the error names the")
        print("library rather than the reordering.")
        return 1

    print("every module touching a vendored library bootstraps its own path first.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
